# `git push` flags that take their value as a SEPARATE following token
# (space-separated form, e.g. `-o ci.skip`) rather than joined with `=`
# (e.g. `--push-option=ci.skip`, which is one token already and needs no
# special handling). Without this table, emit_if_push's positional count
# below treats a flag's own value as a destination positional -- `git push
# -o ci.skip origin` was counted as TWO positionals ("ci.skip" and
# "origin"), which made `bare` false and skipped the branch check
# entirely on what is actually a bare push to the current branch's
# upstream, from main. This is the push-subcommand analog of
# skip_global_opts's is_global_valued -- the two tables cover different
# subcommands (global options between `git` and `push`, versus push's own
# flags after it) and are deliberately kept separate; a flag in one is
# never implicitly a flag in the other.
function is_push_valued_flag(opt) {
    return (opt == "-o" || opt == "--push-option" || opt == "--repo" || \
            opt == "--receive-pack" || opt == "--exec")
}

# For a git invocation starting at TOK[gi]=="git", find the subcommand
# (via skip_global_opts) and, if it is "push", emit one PUSH record.
function emit_if_push(gi,    s, cvlist, cv, k, e, positional, tok1, bare, \
                       lastdir, scan_i, args, skip_next) {
    s = skip_global_opts(TOK, gi + 1, NT)
    if (s == 0 || TOK[s] != "push") return
    cvlist = ""
    for (cv = 1; cv <= NCVALS; cv++) cvlist = cvlist (cv > 1 ? "," : "") CVALS[cv]
    e = s + 1
    while (e <= NT && !is_separator(TOK[e])) e++
    positional = 0
    args = ""
    skip_next = 0
    for (k = s + 1; k < e; k++) {
        if (skip_next) {
            skip_next = 0
        } else if (substr(TOK[k], 1, 1) != "-") {
            positional++
        } else if (is_push_valued_flag(TOK[k]) && k + 1 < e) {
            skip_next = 1
        }
        args = args TOK[k] (k < e - 1 ? " " : "")
    }
    bare = (positional == 0)
    if (positional == 1) {
        # A single positional token with no ":" is a bare remote-only push
        # (push.default decides what actually gets pushed); a token
        # containing ":" is an explicit refspec even alone (HEAD:main).
        # Skip a valued flag's own value the same way the counting loop
        # above does, so it is never mistaken for that one positional.
        tok1 = ""
        skip_next = 0
        for (k = s + 1; k < e; k++) {
            if (skip_next) {
                skip_next = 0
            } else if (substr(TOK[k], 1, 1) != "-") {
                tok1 = TOK[k]
                break
            } else if (is_push_valued_flag(TOK[k]) && k + 1 < e) {
                skip_next = 1
            }
        }
        if (tok1 !~ /:/) bare = 1
    }
